/** The sixteen contract events plus ERC-1155 TransferSingle (mint/burn). */
export const REGISTER_EVENTS = [
  "TypeCreated",
  "TypeConfigured",
  "TypeRetired",
  "TypeRecognised",
  "DelegateSet",
  "OrgPrivateOnlySet",
  "BatchAdded",
  "BatchRevoked",
  "LeafRevoked",
  "Claimed",
  "SelfClaimed",
  "Renounced",
  "Pruned",
  "SourcesProposed",
  "SourcesApplied",
  "SourcesCancelled",
  "TransferSingle",
] as const;
export type RegisterEventName = (typeof REGISTER_EVENTS)[number];
